using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {deserialized}");

// 2) Probe without throwing using TryGetTypeInfo
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {found!.Type.Name}");
}

// Now try a type the resolver doesn't know about (empty resolver)
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

if (limited.TryGetTypeInfo(typeof(Person), out _))
{
    Console.WriteLine("Unexpected: found metadata");
}
else
{
    Console.WriteLine("\nTryGetTypeInfo(Person) on limited resolver: not available (no exception!)");
}

record Person(string Name, int Age);

// A resolver that never resolves anything
sealed class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

